CREATE TABLE unidades_moto (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, modelo_moto_id BIGINT NOT NULL REFERENCES modelos_moto(id), chasis VARCHAR(40) NOT NULL, motor VARCHAR(40) NOT NULL, color VARCHAR(40), estado VARCHAR(20) NOT NULL DEFAULT 'DISPONIBLE', observaciones TEXT,
 creado_por VARCHAR(100) NOT NULL DEFAULT 'sistema', creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), modificado_por VARCHAR(100), modificado_en TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, eliminado BOOLEAN NOT NULL DEFAULT FALSE,
 CONSTRAINT uq_unidades_chasis UNIQUE(chasis), CONSTRAINT uq_unidades_motor UNIQUE(motor),
 CONSTRAINT chk_unidad_estado CHECK(estado IN ('DISPONIBLE','RESERVADA','VENDIDA'))
);
